-- Pelvic floor exercises get their own muscle group (only ones still filed under core).
UPDATE `exercises` SET `muscle_group` = 'pelvic_floor' WHERE `muscle_group` = 'core' AND `name` IN ('Pelvic Floor Lift (Kegel)', 'Pelvic Floor Quick Flicks', 'Pelvic Floor Elevator', 'Pelvic Floor Relaxation Breathing', 'Diaphragmatic Breathing', 'Pelvic Floor Breath (Connection Breath)', 'Pelvic Tilt', 'Transverse Abdominis Activation', 'Heel Slide', 'Knee Fallout', 'Toe Tap (Lying)', 'Bridge with Pelvic Floor Lift', 'Ball Squeeze Bridge', 'Adductor Ball Squeeze', 'Squat with Pelvic Floor Lift', 'Clamshell with Pelvic Floor Lift', 'Happy Baby', 'Deep Squat Hold (Relax)', 'Seated Pelvic Floor Lift', 'Postnatal Dead Bug (Heel Tap)', 'Postnatal Side Plank (Knees)', 'Postnatal Bird Dog');
